from taf.collectors.core import StartableCollector
from taf.collectors.core.templates.dynamic_class_creation import Using
from taf.collectors.core.entities.executor import TimeoutErrorWithData

import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class TtiTraceSnapshotAirphoneCollector(Using("tool_executor"), Using("file_getter"),
                                        StartableCollector):  # type: ignore[misc]
    """
        To Start, Stop and Collect ttitrace snapshot airphone on a given configuration.
    """

    def __init__(self,
                 container='L2RT',
                 script_path='/opt/nokia/tools/eventsTraceCollector/eventsCollect.sh',
                 log_dir='/var/eventsTrace',
                 start_timeout=10,
                 stop_timeout=3,
                 target_file_name=None,
                 **kwargs):
        super(TtiTraceSnapshotAirphoneCollector, self).__init__(**kwargs)
        self._container = container
        self._script_path = script_path
        self._log_dir = log_dir
        self._log_file_name = 'L2TtiTrace_EventsSnapshot.bin.'
        self._stop_timeout = stop_timeout
        self._start_timeout = start_timeout
        self._target_file_name = target_file_name or "{name}.tgz".format(name=self._name)

    def _setup(self):
        self._process_and_file_cleanup()
        self._set_lxc_prefix()

    def _set_lxc_prefix(self):
        container_id = self._tool_executor.execute(
            "for i in $(lxc-ls) ; do echo \"$i $(lxc-attach -n $i -- uname -n)\" ;"
            " done | grep '{container}' | awk '{{print $1;}}'".format(
                container=self._container).encode('utf-8')).strip().decode('utf-8')
        if container_id == "":
            raise Exception("Unable to fetch container_id with container_name "
                            "having substring '{container}'".format(container=self._container))
        self._lxc_prefix = " lxc-attach -n {container_id} --".format(container_id=container_id)

    def _start(self):
        start_command = (
            "{lxc_prefix} {script_path}").format(lxc_prefix=self._lxc_prefix,
                                                 script_path=self._script_path).encode()
        logger.debug("start_command=%r" % start_command)
        self._process = self._tool_executor.start(start_command, use_tty=True)
        self._wait_for_start_completed()

    def _wait_for_start_completed(self):
        try:
            self._process.stdout.read_until_string(b'Small file. Ignoring...', self._start_timeout)
        except TimeoutErrorWithData as data:
            raise Exception("'Small file. Ignoring...' not in: {}".format(data))

    def _stop(self):
        self._process.stdin.write("\x03".encode())
        self._process.wait(timeout=self._stop_timeout)

    def _teardown(self):
        self._process_and_file_cleanup()

    def _collect(self, target_dir):
        ttitrace_file_collect = \
            "cd '{log_dir}' ; find . -name '{log_file_name}*'".format(
                log_dir=self._log_dir,
                log_file_name=self._log_file_name)
        ttitrace_files = " ".join(
            self._tool_executor.execute(ttitrace_file_collect.encode()).decode().strip().split("\n"))
        tar_file_cmd = "cd '{log_dir}' ; tar zcvf tti_trace_event.tgz {ttitrace_files}".format(
            log_dir=self._log_dir,
            ttitrace_files=ttitrace_files
        )
        self._tool_executor.raw_execute(tar_file_cmd.encode())
        self._file_getter.get_file(
            source_path="{log_dir}/tti_trace_event.tgz".format(log_dir=self._log_dir),
            target_path="{target_dir}/{target_file_name}".format(
                target_dir=target_dir, target_file_name=self._target_file_name))

    def _process_and_file_cleanup(self):
        self._tool_executor.raw_execute(
            'pkill -9 -f {script_path}'.format(script_path=self._script_path).encode())
        self._tool_executor.execute(
            "rm -f '{log_dir}/{log_file_name}'*".format(log_dir=self._log_dir,
                                                        log_file_name=self._log_file_name).encode())
